#!/usr/bin/env node
// content-dist drift gate (CLAUDE.md I2, architecture.md §2.2).
//
// content-dist/ is GENERATED by the content build and SHIPPED. It must never be
// hand-edited: any change under content-dist/ must be accompanied by a change
// under content/ (the human-authored source) in the same changeset. A diff in
// content-dist/ with no matching content/ diff means someone edited the built
// bundle directly — exactly what this gate rejects.
//
// "Changeset" = committed diff against a base ref (default origin/main) UNION
// the working tree (staged, unstaged, and untracked). The working-tree union is
// what lets the M0 exit-criteria demo trip the gate with a single hand-edited
// file, no commit required.
import { execFileSync } from 'node:child_process';

const BASE = process.env.DRIFT_BASE || 'origin/main';

function git(args) {
  try {
    // stderr ignored: an unknown base ref is an expected probe failure we
    // recover from via the fallbacks below; we don't want its noise in logs.
    return execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch {
    return '';
  }
}

const changed = new Set();

// Committed diff vs base (tolerate an unknown base ref: fall back progressively).
for (const range of [[`${BASE}...HEAD`], [`${BASE}`, 'HEAD'], ['HEAD~1', 'HEAD']]) {
  const out = git(['diff', '--name-only', ...range]);
  if (out) {
    out.split('\n').filter(Boolean).forEach((f) => changed.add(f));
    break;
  }
}

// Working tree: staged + unstaged + untracked.
const status = git(['status', '--porcelain', '--untracked-files=all']);
for (const line of status.split('\n').filter(Boolean)) {
  // Porcelain: XY<space>path  (path starts at column 4)
  const path = line.slice(3).trim();
  // Renames appear as "old -> new"; take the destination.
  const arrow = path.indexOf(' -> ');
  changed.add(arrow === -1 ? path : path.slice(arrow + 4));
}

const meaningful = (f, prefix) => f.startsWith(prefix) && !f.endsWith('.gitkeep');

const distChanged = [...changed].filter((f) => meaningful(f, 'content-dist/'));
const srcChanged = [...changed].some((f) => meaningful(f, 'content/'));

if (distChanged.length > 0 && !srcChanged) {
  console.error('✗ content-dist drift gate FAILED:\n');
  console.error('  content-dist/ changed with no corresponding change under content/:');
  for (const f of distChanged) console.error('    - ' + f);
  console.error('\n  content-dist/ is generated and shipped; never hand-edit it (I2).');
  console.error('  Edit content/ and regenerate with `pnpm content:build`.');
  process.exit(1);
}

console.log(`✓ content-dist drift gate passed (base ${BASE}; ${distChanged.length} dist change(s), source ${srcChanged ? 'changed' : 'unchanged'}).`);
